macro_rules! deps {
    () => {
        Folder!();
        Split!();
        IntoIter!();
    };
}

macro_rules! Producer {
    () => {
        deps!();
        # [doc = " A `Producer` is effectively a \"splittable `IntoIterator`\". That"] # [doc = " is, a producer is a value which can be converted into an iterator"] # [doc = " at any time: at that point, it simply produces items on demand,"] # [doc = " like any iterator. But what makes a `Producer` special is that,"] # [doc = " *before* we convert to an iterator, we can also **split** it at a"] # [doc = " particular point using the `split_at` method. This will yield up"] # [doc = " two producers, one producing the items before that point, and one"] # [doc = " producing the items after that point (these two producers can then"] # [doc = " independently be split further, or be converted into iterators)."] # [doc = " In Rayon, this splitting is used to divide between threads."] # [doc = " See [the `plumbing` README][r] for further details."] # [doc = ""] # [doc = " Note that each producer will always produce a fixed number of"] # [doc = " items N. However, this number N is not queryable through the API;"] # [doc = " the consumer is expected to track it."] # [doc = ""] # [doc = " NB. You might expect `Producer` to extend the `IntoIterator`"] # [doc = " trait.  However, [rust-lang/rust#20671][20671] prevents us from"] # [doc = " declaring the DoubleEndedIterator and ExactSizeIterator"] # [doc = " constraints on a required IntoIterator trait, so we inline"] # [doc = " IntoIterator here until that issue is fixed."] # [doc = ""] # [doc = " [r]: https://github.com/rayon-rs/rayon/blob/main/src/iter/plumbing/README.md"] # [doc = " [20671]: https://github.com/rust-lang/rust/issues/20671"] pub trait Producer : Send + Sized { # [doc = " The type of item that will be produced by this producer once"] # [doc = " it is converted into an iterator."] type Item ; # [doc = " The type of iterator we will become."] type IntoIter : Iterator < Item = Self :: Item > + DoubleEndedIterator + ExactSizeIterator ; # [doc = " Convert `self` into an iterator; at this point, no more parallel splits"] # [doc = " are possible."] fn into_iter (self) -> Self :: IntoIter ; # [doc = " The minimum number of items that we will process"] # [doc = " sequentially. Defaults to 1, which means that we will split"] # [doc = " all the way down to a single item. This can be raised higher"] # [doc = " using the [`with_min_len`] method, which will force us to"] # [doc = " create sequential tasks at a larger granularity. Note that"] # [doc = " Rayon automatically normally attempts to adjust the size of"] # [doc = " parallel splits to reduce overhead, so this should not be"] # [doc = " needed."] # [doc = ""] # [doc = " [`with_min_len`]: super::IndexedParallelIterator::with_min_len()"] fn min_len (& self) -> usize { 1 } # [doc = " The maximum number of items that we will process"] # [doc = " sequentially. Defaults to MAX, which means that we can choose"] # [doc = " not to split at all. This can be lowered using the"] # [doc = " [`with_max_len`] method, which will force us to create more"] # [doc = " parallel tasks. Note that Rayon automatically normally"] # [doc = " attempts to adjust the size of parallel splits to reduce"] # [doc = " overhead, so this should not be needed."] # [doc = ""] # [doc = " [`with_max_len`]: super::IndexedParallelIterator::with_max_len()"] fn max_len (& self) -> usize { usize :: MAX } # [doc = " Split into two producers; one produces items `0..index`, the"] # [doc = " other `index..N`. Index must be less than or equal to `N`."] fn split_at (self , index : usize) -> (Self , Self) ; # [doc = " Iterate the producer, feeding each element to `folder`, and"] # [doc = " stop when the folder is full (or all elements have been consumed)."] # [doc = ""] # [doc = " The provided implementation is sufficient for most iterables."] fn fold_with < F > (self , folder : F) -> F where F : Folder < Self :: Item > , { folder . consume_iter (self . into_iter ()) } }
    };
}

Producer!();